/** What an approval rule measures: the document value or its total quantity. */
export enum ApprovalMetric {
    Amount = "Amount",
    Quantity = "Quantity",
}

export interface ApprovalRuleDto {
    id: string;
    docType: DocumentType;
    /** Money. Null for a caller without `cost.view` (the Warehouse staff), and when the rule has no amount threshold. */
    amountThreshold: number | undefined;
    qtyThreshold: number | undefined;
    approverTier: ApproverTier;
    /** Deprecated: the system role that holds the tier by default (Supervisor for Standard, Owner for Large), for a client that has not moved to ApproverTier. */
    roleRequired: string;
    isActive: boolean;
}

export interface ApprovalRuleSaveRequest {
    docType: DocumentType;
    amountThreshold: number | undefined;
    qtyThreshold: number | undefined;
    isActive?: boolean;
    approverTier?: ApproverTier | undefined;
}

/** One reason a document needs approval: Actual reached Threshold of a rule that asks for ApproverTier. For an amount rule the two numbers are money, so a caller without `cost.view` (the Warehouse staff) gets them as null: they still see that the document needs approval and which kind of rule fired (Metric), not the amount. A quantity rule is not hidden. RoleRequired is deprecated: the system role that holds the tier by default (Supervisor for Standard, Owner for Large). */
export interface ApprovalTriggerDto {
    metric: ApprovalMetric;
    threshold: number | undefined;
    actual: number | undefined;
    approverTier: ApproverTier;
    roleRequired: string;
}

export interface ApproveRequest {
    /** Required when the document `requiresOverride`: why the approver lets stock go below zero. Ignored for any other document. */
    negativeStockOverrideReason: string | undefined;
}

/** Who may satisfy an approval rule: a holder of string Permissions.DocumentApprove (Standard) or of string Permissions.DocumentApproveLarge (Large). Two levels by design; a third is a new permission and a migration. The values are what the rule stores once it keeps a tier (ADR roles-permissions 4.1). */
export enum ApproverTier {
    Standard = "Standard",
    Large = "Large",
}

/** A role the caller may give to a user: the code the user is saved with and the name people read. No permission list: a user manager need not see what a role holds. */
export interface AssignableRoleDto {
    code: string;
    name: string;
}

export interface AttachmentDto {
    /** The attachment's public id. */
    id: string;
    ownerType: AttachmentOwnerType;
    /** The public id of the owner: of a document when `OwnerType` is Document, of a product when it is Product. */
    ownerId: string;
    fileName: string;
    contentType: string;
    sizeBytes: number;
    uploadedBy: string;
    uploadedAt: string;
}

/** What a file is attached to. Adding an owner type means adding one owner policy in the application layer. */
export enum AttachmentOwnerType {
    Document = "Document",
    Product = "Product",
}

/** What the audit log filters can be offered as dropdowns: the entity names and action names an audit row can carry. */
export interface AuditFilterOptions {
    entityTypes: string[];
    actions: string[];
}

export interface AuditLogDto {
    actor: string;
    action: string;
    entityType: string;
    entityId: string;
    /** JSON. A key that names a cost or value is left out for a caller without the permission that unlocks it. */
    before: string | undefined;
    /** JSON, with the same rule as Before. */
    after: string | undefined;
    at: string;
}

/** The result of a login or refresh. RefreshToken is null when the API is configured to deliver the refresh token only in its HttpOnly cookie (Auth:ReturnRefreshTokenInBody=false). */
export interface AuthResult {
    accessToken: string;
    expiresAt: string;
    /** DEPRECATED. The refresh token now travels in an HttpOnly cookie; this property is null unless Auth:ReturnRefreshTokenInBody is switched on (off by default). */
    refreshToken: string | undefined;
    user: UserInfo;
}

export interface CancelRequest {
    reason: string | undefined;
}

export interface CategoryDto {
    id: string;
    name: string;
}

export interface CategorySaveRequest {
    name: string;
}

export interface ChangePasswordRequest {
    currentPassword: string;
    newPassword: string;
}

export interface CloseRequest {
    /** Why what is still to come will not come: required, at least 5 characters once trimmed. */
    reason: string | undefined;
}

/** The numbers behind the Home tiles and menu badges, for the signed-in user, within the warehouses they may see. */
export interface DocumentCounts {
    /** Drafts I created that a reviewer sent back. */
    returnedToMe: number;
    /** All my Drafts (returned ones included). */
    myDrafts: number;
    /** Documents posted since local midnight (Asia/Kuala_Lumpur, BR-10), whoever posted them, that are still Posted: a document reversed since is not counted, so this equals the Posted list filtered to today. */
    postedToday: number;
    /** Submitted documents held for approval that I could act on: not mine to approve when self-approval is off, only large ones for the Owner, none large for a Supervisor, zero for roles that cannot approve. */
    approvalsWaiting: number;
}

export interface DocumentDto {
    id: string;
    type: DocumentType;
    no: string;
    status: DocumentStatus;
    warehouseId: string;
    warehouseName: string;
    partnerId: string | undefined;
    partnerName: string | undefined;
    purpose: IssuePurpose | undefined;
    remark: string | undefined;
    /** An approval rule fired when the document was submitted (false for a Draft). */
    requiresApproval: boolean;
    /** An issue was submitted although stock is short (negative stock is allowed): the approver must give a reason when approving, which forces approval whatever the value thresholds say. A fact about the moment of submission: it stays true after approval and posting; the stored reason is in `NegativeStockOverrideReason`. */
    requiresOverride: boolean;
    /** The approval rule that fired needs a role above Supervisor (for example the Owner). */
    isLarge: boolean;
    /** A Draft that a reviewer sent back (`RejectionReason` holds why, `ReturnedBy*` who). */
    isReturned: boolean;
    rejectionReason: string | undefined;
    cancelReason: string | undefined;
    reversalReason: string | undefined;
    /** Why the approver let stock go below zero; set when a document that `requiresOverride` is approved, otherwise null. */
    negativeStockOverrideReason: string | undefined;
    createdById: string;
    createdBy: string;
    createdByName: string;
    createdAt: string;
    submittedById: string | undefined;
    submittedBy: string | undefined;
    submittedByName: string | undefined;
    submittedAt: string | undefined;
    approvedBy: string | undefined;
    approvedByName: string | undefined;
    approvedAt: string | undefined;
    postedBy: string | undefined;
    postedByName: string | undefined;
    postedAt: string | undefined;
    reversedBy: string | undefined;
    reversedByName: string | undefined;
    /** When a Reversed document was reversed, with `ReversedBy` and `ReversedByName` the user who did it ("Reversed by {name} on {date}"); null otherwise. `ReversalReason` holds why. */
    reversedAt: string | undefined;
    returnedById: string | undefined;
    returnedBy: string | undefined;
    returnedByName: string | undefined;
    returnedAt: string | undefined;
    totalQty: number;
    /** Value of the document: receipts at their entered cost; an issue at its booked cost once posted, and before that at the average cost when it was last saved or submitted (see `AmountIsEstimate`). For a Submitted document this is the value the approval rules were tested against. Null for a caller without `cost.view` (the Warehouse staff). */
    totalAmount: number | undefined;
    lines: DocumentLineDto[];
    /** What the caller may do right now (edit, submit, recall, approve, reject, cancel, post, reverse). The UI shows buttons from this list only. It already accounts for ownership (Warehouse staff and Clerk act only on their own documents), the approver the document is routed to (an Owner reviews only `isLarge` documents, a Supervisor the rest) and self-approval, so a listed action is one the API will accept. */
    allowedActions: string[];
    /** While the document is Submitted or Approved and an approval rule held it back: which thresholds it reaches (value or quantity), for the approver and the "sent for approval" message. Empty otherwise, and when only a negative-stock override (`requiresOverride`) sent it to approval. */
    approvalTriggers: ApprovalTriggerDto[];
    purchaseOrder?: LinkedPurchaseOrder | undefined;
    /** True for an issue that has not posted yet: its lines carry the average cost seen when it was last saved or submitted, and posting books the real cost. Label the amount "estimated". */
    amountIsEstimate: boolean;
    /** Changes whenever the document (header, status or lines) changes; opaque (a keyed hash bound to this document, not a counter): compare it only for equality. Also sent as the ETag header; send it back as If-Match to refuse a stale save. */
    concurrencyToken: string;
}

export interface DocumentLineDto {
    productId: string;
    sku: string;
    productName: string;
    qty: number;
    uomId: string;
    uomCode: string;
    baseQty: number;
    /** The cost per ENTERED unit (the unit in `UomCode`), in money (2 decimals), that a person TYPED: send it back unchanged to keep the line. For a line whose cost nobody typed (`CostFromAverage`) it is `null`: there is nothing to edit, the line is valued at the average (see `BaseUnitCost` and `Amount`). For a typed cost `qty x unitCost` is the line `amount`. Null for a caller without `cost.view` (the Warehouse staff). */
    unitCost: number | undefined;
    /** The cost per BASE unit, for stock valuation, shown as a UNIT PRICE with 4 decimals (not money): a carton price spread over the pieces in it (1 carton of 3 at 10.00 is 3.3333; a carton of 1,000 at 3.00 is 0.0030), or the average for a line at the average. Amounts computed from it are money (2 decimals). Never send it back as `unitCost`. Null for a caller without `cost.view`. */
    baseUnitCost: number | undefined;
    /** The value of the line, in money, stored when the line was saved: `round(qty x unitCost, 2)` for a typed cost, `round(baseQty x average, 2)` for a line at the average. It is the only figure to add up: a document total is the sum of the line `amount`s (never `qty x unitCost` of the lines: that is wrong for a line at the average). Null for a caller without `cost.view`. */
    amount: number | undefined;
    /** Nobody typed this line's cost: it is valued at the average cost of the product (every issue line; a receipt line saved by someone who may not enter cost, such as the Warehouse staff). It has no editable cost (`unitCost` is null), and saving the draft without a cost for it keeps it at the average; typing a cost makes it a typed cost. Show its `amount` and `baseUnitCost` read-only. On a draft its amount is re-valued at the current average on every save and at post, so a draft read earlier can be stale. */
    costFromAverage: boolean;
    remark: string | undefined;
    /** On hand in the document's warehouse right now, in base units (compare with `BaseQty`; lines of one product add up). Null once the document is Posted, Reversed or Cancelled, when the figure no longer says anything about this document. */
    available?: number | undefined;
    /** On a receipt created from a purchase order: the order line this line receives (its `lineNo`); null otherwise, and omitted while the Purchasing module is off. Send it back unchanged when saving the draft. */
    purchaseOrderLineNo?: number | undefined;
}

export interface DocumentLineInput {
    productId: string;
    qty: number;
    uomId: string | undefined;
    unitCost: number | undefined;
    remark: string | undefined;
    /** Only on a receipt created from a purchase order (`POST /api/purchase-orders/{id}/receipt`): the `lineNo` of the purchase order line this line receives. Every line of such a receipt must name one (a save without it is a 400 and the link is kept), the line's product and unit must be the order line's, and the quantities named for one order line must not exceed what remains of it. On any other document it must be left out (a 400 otherwise), and it is a 400 "not available" while the Purchasing module is off. The link itself is never sent and never changes: it is set when the receipt is created. */
    purchaseOrderLineNo?: number | undefined;
}

export interface DocumentListItem {
    id: string;
    type: DocumentType;
    no: string;
    status: DocumentStatus;
    warehouseName: string;
    partnerName: string | undefined;
    createdAt: string;
    postedAt: string | undefined;
    totalQty: number;
    /** Same meaning as on the full document: an unposted issue is valued at the average cost seen when it was last saved or submitted (`AmountIsEstimate`). Null for a caller without `cost.view` (the Warehouse staff). */
    totalAmount: number | undefined;
    createdBy: string;
    createdById: string;
    createdByName: string;
    submittedById: string | undefined;
    submittedBy: string | undefined;
    submittedByName: string | undefined;
    submittedAt: string | undefined;
    /** An approval rule fired when the document was submitted. With `status=Submitted` this is the approvals inbox. */
    requiresApproval: boolean;
    requiresOverride: boolean;
    isLarge: boolean;
    /** A Draft that a reviewer sent back. */
    isReturned: boolean;
    /** Same value as `concurrencyToken` on the full document: compare it to know whether an open document has gone stale. */
    concurrencyToken: string;
    /** True for an issue that has not posted yet: `totalAmount` is an estimate at the average cost seen when it was last saved or submitted. */
    amountIsEstimate: boolean;
    /** The caller may approve or reject this document right now: it is Submitted and held for approval, routed to the caller's role
(an Owner reviews only `isLarge` documents, a Supervisor the rest, an Admin all) and, unless self-approval is on, not submitted by the caller.
This is exactly the rule behind the "waiting for approval" count. A single document's `allowedActions` additionally tests the live approval rules. */
    canAct: boolean;
}

export interface DocumentSaveRequest {
    warehouseId: string;
    partnerId: string | undefined;
    purpose: IssuePurpose | undefined;
    remark: string | undefined;
    lines: DocumentLineInput[];
}

/** Figure 5 state machine. Rejection returns to Draft (reason kept on the document). */
export enum DocumentStatus {
    Draft = "Draft",
    Submitted = "Submitted",
    Approved = "Approved",
    Posted = "Posted",
    Reversed = "Reversed",
    Cancelled = "Cancelled",
}

/** The kind of a document, and the subject an ApprovalRule is written for. DocumentType.PurchaseOrder and DocumentType.SalesOrder are not stock documents (an order is its own aggregate and moves no stock, plans PL2 D2 and PL3 D1): it is here only so that the approval rules and their two tiers are reused for it. StockDocument StockDocument.Create(DocumentType type, Warehouse warehouse, Partner? partner, IssuePurpose? purpose, string? remark, int createdBy, DateTime now) refuses it and StockDirection has no direction for it. */
export enum DocumentType {
    Receipt = "Receipt",
    Issue = "Issue",
    Transfer = "Transfer",
    Adjust = "Adjust",
    PurchaseOrder = "PurchaseOrder",
    SalesOrder = "SalesOrder",
}

export interface ImportResult {
    committed: boolean;
    total: number;
    valid: number;
    invalid: number;
    /** Rows that create (a preview reports what a commit would create). */
    created: number;
    /** Rows that update an existing record (a preview reports what a commit would update). */
    updated: number;
    /** The public id of the first draft receipt a committed opening-stock import created; null for a preview and for other imports. */
    documentId: string | undefined;
    rows: ImportRowResult[];
}

export interface ImportRowResult {
    row: number;
    key: string;
    /** False when the row has errors and blocks the import. */
    ok: boolean;
    /** New or Update for a valid row (what a commit would do with it; the same in a preview and after a commit), Error otherwise. A valid row can still carry a note in `Errors` (for example "unit not changed"). */
    status: ImportRowStatus;
    errors: string[];
}

