export interface LowStockAlert {
    productId: string;
    sku: string;
    productName: string;
    /** Null (with the code and the name) only for a product stocked in no warehouse the caller can see. It appears ONCE, not once per warehouse. */
    warehouseId: string | undefined;
    warehouseCode: string | undefined;
    warehouseName: string | undefined;
    /** Zero for a product that is stocked in no warehouse the caller can see (it has no balance row there: it is listed once, with no warehouse). Negative when stock went below zero. */
    qtyOnHand: number;
    safetyStock: number;
    /** Safety stock minus on hand: how many units are missing (more than the safety level when the balance is negative). */
    shortfall: number;
    /** On hand is below zero: show it as a warning, not just as "low". */
    isNegative: boolean;
}

/** A module and whether this installation has it on. `Requires` lists the codes of modules that must be on first (none yet). */
export interface ModuleDto {
    code: string;
    name: string;
    description: string;
    enabled: boolean;
    requires: string[];
}

/** Turn a module on or off. `Enabled` has no default on purpose: a body that leaves it out is a 400, never a quiet switch off. The reason is kept in the audit log. */
export interface ModuleSwitchRequest {
    enabled: boolean | undefined;
    reason: string;
}

/** What a module switch answers: the module as `GET /api/modules` lists it, plus how many roles got permissions back. A module's permissions are kept, hidden, on the roles that hold them while it is off; turning it on gives them back at once, so this count is the warning. It is 0 when the module was turned off, was already in the state asked for, or has no permissions. */
export interface ModuleSwitchResult {
    code: string;
    name: string;
    description: string;
    enabled: boolean;
    requires: string[];
    /** Live roles that hold at least one permission of the module and so have it in force again. */
    rolesRegainingGrants: number;
}

/** One line of the receipt/issue detail. A document reversed since posting has two rows per line: the posting and the reversal. */
export interface MovementRow {
    /** When the movement happened: the posting time, or for a reversal row the time of the reversal. */
    postedAt: string;
    docNo: string;
    type: DocumentType;
    status: DocumentStatus;
    warehouseCode: string;
    partner: string | undefined;
    sku: string;
    productName: string;
    /** As entered, unsigned, in the line's own unit. Unchanged by decimal MovementRow.StockEffect. */
    qty: number;
    uomCode: string;
    /** Unsigned, in the product's base unit. */
    baseQty: number;
    /** Signed, in base units: positive when the movement adds stock, negative when it removes stock. A receipt adds, an issue removes, and the reversal row of a document does the opposite of its posting. Summed over a product and a period (a date range on `PostedAt`) it equals the change in the product's stock balance. */
    stockEffect: number;
    /** Per base unit. Null for a caller without `cost.view`. */
    unitCost: number | undefined;
    /** Base quantity times unit cost. Null for a caller without `cost.view`. */
    amount: number | undefined;
    /** The row is the reversal of the posting shown in the row for the same document and line. */
    isReversal: boolean;
}

